/**
 * Mirror of the host seam (docs/adr/0002) as JSON for the hosts
 * (buildytech/vibechat-desktop reads it from its third_party/studio pin in a
 * contract test). Generated by `bun run gen:host-seam`; never edit by hand.
 */
import {
  DESKTOP_TUNNEL_USER,
  DesktopConnectionSchema,
  HOST_DESKTOP_ROUTES,
  HOST_MIN_CLIENT_PROTOCOL,
  HOST_PROTOCOL,
  HOST_REMOTE_ROUTES,
  HOST_SEAM_PREFIX,
  HOST_SEAM_ROUTES,
  HOST_SEAM_VERSION,
  HOST_SESSION_COOKIE,
  HOST_SESSION_PATH,
  HOST_TICKET_PARAM,
  HOST_TICKET_TTL_SECONDS,
  HostCapabilitiesSchema,
  HostHelloSchema,
} from "../../packages/agent-contract/src/host"

export const HOST_SEAM_JSON_PATH = "packages/agent-contract/host-seam.json"

export function hostSeamJson(): string {
  const doc = {
    $comment: "Generated by `bun run gen:host-seam` from packages/agent-contract/src/host.ts (docs/adr/0002). Do not edit.",
    seam: HOST_SEAM_VERSION,
    prefix: HOST_SEAM_PREFIX,
    capabilities: Object.keys(HostCapabilitiesSchema.shape),
    routes: HOST_SEAM_ROUTES.map((r) => (r.sse ? { ...r } : { method: r.method, path: r.path })),
    protocol: HOST_PROTOCOL,
    minClientProtocol: HOST_MIN_CLIENT_PROTOCOL,
    hello: Object.keys(HostHelloSchema.shape),
    auth: {
      sessionPath: HOST_SESSION_PATH,
      cookie: HOST_SESSION_COOKIE,
      ticketParam: HOST_TICKET_PARAM,
      ticketTtlSeconds: HOST_TICKET_TTL_SECONDS,
    },
    remote: HOST_REMOTE_ROUTES.map((r) => ({ method: r.method, path: r.path })),
    desktop: HOST_DESKTOP_ROUTES.map((r) => ({ method: r.method, path: r.path })),
    desktopConnection: Object.keys(DesktopConnectionSchema.shape),
    tunnelUser: DESKTOP_TUNNEL_USER,
  }
  return `${JSON.stringify(doc, null, 2)}\n`
}
